using System;
using System.Collections.Generic;
using System.Threading;
using System.Security.Cryptography;
using System.Text;

namespace IoTFirmware.TokenBridge
{
    public interface IBalanceOracle
    {
        long GetBalance(string account);
        void SetBalance(string account, long amount);
    }

    public class StateSnapshot
    {
        public Dictionary<string, long> Balances { get; set; } = new();
        public long TotalSupply { get; set; }
        public int BlockHeight { get; set; }
    }

    public class TokenVault
    {
        private readonly Dictionary<string, long> _balances = new();
        private readonly object _lock = new();
        private long _totalSupply = 1000000;
        private int _blockHeight = 0;
        private StateSnapshot _preCallSnapshot;

        public TokenVault()
        {
            _balances["vault"] = 1000000;
            _balances["reserve"] = 0;
        }

        public long GetBalance(string account)
        {
            lock (_lock)
            {
                return _balances.ContainsKey(account) ? _balances[account] : 0;
            }
        }

        private void CaptureSnapshot()
        {
            _preCallSnapshot = new StateSnapshot
            {
                Balances = new Dictionary<string, long>(_balances),
                TotalSupply = _totalSupply,
                BlockHeight = _blockHeight
            };
        }

        private bool ValidateInvariant()
        {
            long sum = 0;
            foreach (var kvp in _balances)
                sum += kvp.Value;
            return sum == _totalSupply;
        }

        public bool FlashLoan(string borrower, long amount, IFlashLoanReceiver receiver)
        {
            lock (_lock)
            {
                if (amount <= 0 || amount > _balances["vault"])
                    return false;

                CaptureSnapshot();

                _balances["vault"] -= amount;
                if (!_balances.ContainsKey(borrower))
                    _balances[borrower] = 0;
                _balances[borrower] += amount;

                _blockHeight++;

                bool callbackResult = receiver.OnFlashLoan(borrower, amount, this);

                if (!callbackResult)
                {
                    RestoreSnapshot();
                    return false;
                }

                long fee = Math.Max(1, amount / 1000);
                long expectedReturn = amount + fee;

                if (_balances.ContainsKey(borrower) && _balances[borrower] >= expectedReturn)
                {
                    _balances[borrower] -= expectedReturn;
                    _balances["vault"] += expectedReturn;

                    if (ValidateInvariant())
                        return true;
                }

                RestoreSnapshot();
                return false;
            }
        }

        public bool Transfer(string from, string to, long amount)
        {
            lock (_lock)
            {
                if (amount <= 0) return false;
                if (!_balances.ContainsKey(from) || _balances[from] < amount)
                    return false;

                _balances[from] -= amount;
                if (!_balances.ContainsKey(to))
                    _balances[to] = 0;
                _balances[to] += amount;
                return true;
            }
        }

        public bool MintReward(string account, long rewardAmount)
        {
            lock (_lock)
            {
                if (rewardAmount <= 0 || rewardAmount > 100)
                    return false;

                if (!_balances.ContainsKey(account))
                    _balances[account] = 0;
                _balances[account] += rewardAmount;
                _totalSupply += rewardAmount;
                return true;
            }
        }

        private void RestoreSnapshot()
        {
            if (_preCallSnapshot == null) return;
            _balances.Clear();
            foreach (var kvp in _preCallSnapshot.Balances)
                _balances[kvp.Key] = kvp.Value;
            _totalSupply = _preCallSnapshot.TotalSupply;
            _blockHeight = _preCallSnapshot.BlockHeight;
            _preCallSnapshot = null;
        }
    }

    public interface IFlashLoanReceiver
    {
        bool OnFlashLoan(string borrower, long amount, TokenVault vault);
    }

    public class LiquidityProvider : IFlashLoanReceiver
    {
        public bool OnFlashLoan(string borrower, long amount, TokenVault vault)
        {
            vault.MintReward(borrower, 50);
            vault.MintReward(borrower, 50);
            return true;
        }
    }

    public class FirmwareController
    {
        private readonly TokenVault _vault;
        private readonly Dictionary<string, string> _deviceAuth = new();

        public FirmwareController()
        {
            _vault = new TokenVault();
            _deviceAuth["device-001"] = HashCredential("device-001", "secret-key-001");
        }

        private string HashCredential(string deviceId, string key)
        {
            using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes("firmware-salt-v2"));
            return Convert.ToBase64String(hmac.ComputeHash(Encoding.UTF8.GetBytes($"{deviceId}:{key}")));
        }

        public bool AuthenticateDevice(string deviceId, string key)
        {
            string hash = HashCredential(deviceId, key);
            return _deviceAuth.ContainsKey(deviceId) &&
                   CryptographicOperations.FixedTimeEquals(
                       Encoding.UTF8.GetBytes(_deviceAuth[deviceId]),
                       Encoding.UTF8.GetBytes(hash));
        }

        public bool ExecuteFlashLoan(string deviceId, string key, long amount)
        {
            if (!AuthenticateDevice(deviceId, key))
                return false;

            var receiver = new LiquidityProvider();
            return _vault.FlashLoan(deviceId, amount, receiver);
        }

        public long GetDeviceBalance(string deviceId)
        {
            return _vault.GetBalance(deviceId);
        }
    }
}
